def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    cr = sum(r for r, c in pts) / len(pts)
    cc = sum(c for r, c in pts) / len(pts)
    out = [row[:] for row in grid]

    colors = set(grid[r][c] for r, c in pts)
    for color in colors:
        cells = [(r, c) for r, c in pts if grid[r][c] == color]
        if len(cells) < 2:
            continue
        # Select the pair of cells that forms a neighboring diagonal segment.
        pair = None
        for i, (r1, c1) in enumerate(cells):
            for r2, c2 in cells[i+1:]:
                dr, dc = r2-r1, c2-c1
                if abs(dr) == 1 and abs(dc) == 1:
                    pair = ((r1, c1), (r2, c2), dr, dc)
                    break
            if pair:
                break
        if not pair:
            continue
        (r1, c1), (r2, c2), dr, dc = pair
        # Continue the diagonal from the endpoint farther from the cluster center.
        d1 = (r1-cr)**2 + (c1-cc)**2
        d2 = (r2-cr)**2 + (c2-cc)**2
        if d1 > d2:
            r, c, sr, sc = r1, c1, -dr, -dc
        else:
            r, c, sr, sc = r2, c2, dr, dc
        while 0 <= r+sr < h and 0 <= c+sc < w:
            r, c = r+sr, c+sc
            if out[r][c] == bg:
                out[r][c] = color
    return out
